pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title DungeonItems
 * @notice Separate contract for Items to avoid ERC721/ERC1155 inheritance collision.
 *         Owned by DungeonCrawler.
 */
contract DungeonItems is ERC1155, Ownable {
    constructor(string memory uri_) ERC1155(uri_) {}

    // Only the Game contract (owner) can mint items as rewards/refunds
    function mint(address to, uint256 id, uint256 amount, bytes memory data) external onlyOwner {
        _mint(to, id, amount, data);
    }

    // Only the Game contract (owner) can burn items (equipping mechanic)
    // This allows the game to manage inventory state without requiring user ApprovalForAll
    // assuming the Items contract is trusted and tightly coupled.
    function burnFrom(address account, uint256 id, uint256 amount) external onlyOwner {
        _burn(account, id, amount);
    }
}

/**
 * @title DungeonCrawler
 * @notice Fully on-chain RPG. Heroes are ERC721.
 * @dev Implements a Commit-Reveal loop using future blockhashes.
 */
contract DungeonCrawler is ERC721, Ownable, ReentrancyGuard {
    using Strings for uint256;

    // --- Structs ---

    struct HeroStats {
        uint32 level;
        uint32 xp;
        uint16 str;
        uint16 dex;
        uint16 intl;
        uint16 hp;
    }

    struct Action {
        uint64 targetBlock;
        uint8 actionType; // 1: Explore
        uint8 difficulty;
    }

    struct Equipment {
        uint256 weaponId;
        uint256 armorId;
        uint256 accessoryId;
    }

    // --- Configuration Constants ---

    uint256 public constant ACTION_COOLDOWN_BLOCKS = 2; 
    uint256 public constant BLOCKHASH_WINDOW = 250;
    uint256 public constant MAX_HERO_SUPPLY = 10000;

    // Items
    uint256 public constant ID_POTION_HEAL = 1;
    uint256 public constant ID_SWORD_BASIC = 101;
    uint256 public constant ID_ARMOR_LEATHER = 201;

    // Slots
    uint8 public constant SLOT_WEAPON = 1;
    uint8 public constant SLOT_ARMOR = 2;
    uint8 public constant SLOT_ACCESSORY = 3;

    // --- State Variables ---

    DungeonItems public itemsContract;
    uint256 public nextHeroId;

    mapping(uint256 => HeroStats) public heroStats;
    mapping(uint256 => Equipment) public heroEquipment;
    mapping(uint256 => Action) public pendingActions;

    // --- Events ---

    event HeroMinted(address indexed owner, uint256 heroId, uint16 str, uint16 dex, uint16 intl);
    event ActionStarted(uint256 indexed heroId, uint8 difficulty, uint256 targetBlock);
    event ActionResolved(uint256 indexed heroId, bool success, uint256 xpGained, uint256 lootId);
    event LevelUp(uint256 indexed heroId, uint32 newLevel);
    event ItemEquipped(uint256 indexed heroId, uint256 itemId, uint8 slot);
    event ItemUnequipped(uint256 indexed heroId, uint256 itemId, uint8 slot);

    // --- Constructor ---

    constructor() ERC721("DungeonHeroes", "HERO") {
        nextHeroId = 1;
        // Deploy the items contract and retain ownership
        itemsContract = new DungeonItems("https://api.dungeoncrawler.game/items/{id}");
    }

    // --- Player Actions: Hero Management ---

    function mintHero() external nonReentrant {
        require(nextHeroId <= MAX_HERO_SUPPLY, "Max supply reached");
        uint256 id = nextHeroId++;

        _safeMint(msg.sender, id);

        // Pseudo-random stats seeded by mint time/sender
        uint256 seed = uint256(keccak256(abi.encodePacked(block.timestamp, msg.sender, id)));

        heroStats[id] = HeroStats({
            level: 1,
            xp: 0,
            str: uint16((seed % 10) + 5),
            dex: uint16(((seed >> 10) % 10) + 5),
            intl: uint16(((seed >> 20) % 10) + 5),
            hp: 100
        });

        emit HeroMinted(msg.sender, id, heroStats[id].str, heroStats[id].dex, heroStats[id].intl);
    }

    function equipItem(uint256 heroId, uint256 itemId, uint8 slot) external nonReentrant {
        require(ownerOf(heroId) == msg.sender, "Not hero owner");
        require(pendingActions[heroId].targetBlock == 0, "Hero is busy");

        bool valid = false;
        if (slot == SLOT_WEAPON && itemId >= 100 && itemId < 200) valid = true;
        if (slot == SLOT_ARMOR && itemId >= 200 && itemId < 300) valid = true;
        if (slot == SLOT_ACCESSORY && itemId >= 300) valid = true;
        require(valid, "Invalid item for slot");

        Equipment storage equip = heroEquipment[heroId];
        uint256 existingItem = 0;

        if (slot == SLOT_WEAPON) {
            existingItem = equip.weaponId;
            equip.weaponId = itemId;
        } else if (slot == SLOT_ARMOR) {
            existingItem = equip.armorId;
            equip.armorId = itemId;
        } else if (slot == SLOT_ACCESSORY) {
            existingItem = equip.accessoryId;
            equip.accessoryId = itemId;
        }

        if (existingItem != 0) {
            // Return old item to user
            itemsContract.mint(msg.sender, existingItem, 1, "");
        }

        // Burn new item from user (Lock into equipment)
        itemsContract.burnFrom(msg.sender, itemId, 1);

        emit ItemEquipped(heroId, itemId, slot);
    }

    function unequipItem(uint256 heroId, uint8 slot) external nonReentrant {
        require(ownerOf(heroId) == msg.sender, "Not hero owner");
        require(pendingActions[heroId].targetBlock == 0, "Hero is busy");

        Equipment storage equip = heroEquipment[heroId];
        uint256 itemId = 0;

        if (slot == SLOT_WEAPON) {
            itemId = equip.weaponId;
            equip.weaponId = 0;
        } else if (slot == SLOT_ARMOR) {
            itemId = equip.armorId;
            equip.armorId = 0;
        } else if (slot == SLOT_ACCESSORY) {
            itemId = equip.accessoryId;
            equip.accessoryId = 0;
        }

        require(itemId != 0, "Slot empty");

        // Return item to user
        itemsContract.mint(msg.sender, itemId, 1, "");

        emit ItemUnequipped(heroId, itemId, slot);
    }

    // --- Player Actions: Dungeon Loop ---

    function enterDungeon(uint256 heroId, uint8 difficulty) external {
        require(ownerOf(heroId) == msg.sender, "Not hero owner");
        require(pendingActions[heroId].targetBlock == 0, "Action pending");
        require(difficulty >= 1 && difficulty <= 5, "Invalid difficulty");

        // Target block for randomness
        uint64 target = uint64(block.number + ACTION_COOLDOWN_BLOCKS);

        pendingActions[heroId] = Action({
            targetBlock: target,
            actionType: 1, // Explore
            difficulty: difficulty
        });

        emit ActionStarted(heroId, difficulty, target);
    }

    function resolveDungeon(uint256 heroId) external nonReentrant {
        Action memory action = pendingActions[heroId];

        require(action.targetBlock != 0, "No pending action");
        require(block.number > action.targetBlock, "Too early");
        require(block.number <= action.targetBlock + BLOCKHASH_WINDOW, "Action expired");

        bytes32 bHash = blockhash(action.targetBlock);
        require(bHash != bytes32(0), "Blockhash not available");

        delete pendingActions[heroId];

        uint256 seed = uint256(keccak256(abi.encodePacked(bHash, heroId, "DUNGEON")));
        _processEncounter(heroId, action.difficulty, seed);
    }

    function resetStuckHero(uint256 heroId) external {
        require(ownerOf(heroId) == msg.sender, "Not hero owner");
        Action memory action = pendingActions[heroId];
        require(action.targetBlock != 0, "No pending action");
        // Only allow reset if blockhash is no longer available
        require(block.number > action.targetBlock + BLOCKHASH_WINDOW, "Not expired yet");

        delete pendingActions[heroId];
    }

    // --- Internal Game Logic ---

    function _processEncounter(uint256 heroId, uint8 difficulty, uint256 seed) internal {
        HeroStats storage stats = heroStats[heroId];
        Equipment memory equip = heroEquipment[heroId];

        uint256 power = stats.str + stats.dex;
        if (equip.weaponId != 0) power += 10;
        if (equip.armorId != 0) power += 5;

        // Calculate success chance
        uint256 successChance = 50;
        uint256 difficultyFactor = difficulty * 15;

        if (power >= difficultyFactor) {
            successChance += (power - difficultyFactor);
        } else {
            uint256 penalty = difficultyFactor - power;
            if (penalty < successChance) successChance -= penalty;
            else successChance = 5;
        }

        if (successChance > 95) successChance = 95;

        uint256 roll = seed % 100;
        bool success = roll < successChance;

        uint32 xpGain = 10;
        uint256 lootId = 0;

        if (success) {
            xpGain = uint32(difficulty * 50) + uint32(stats.intl * 2);

            // 40% chance of loot
            uint256 lootRoll = (seed >> 16) % 100;
            if (lootRoll < 40) {
                lootId = _getLootId(difficulty, (seed >> 32));
                itemsContract.mint(ownerOf(heroId), lootId, 1, "");
            }
        }

        stats.xp += xpGain;
        uint32 requiredXp = stats.level * 1000;

        if (stats.xp >= requiredXp) {
            stats.level++;
            stats.xp -= requiredXp;
            // Stat growth
            stats.str += 1;
            stats.dex += 1;
            stats.intl += 1;
            stats.hp += 10;
            emit LevelUp(heroId, stats.level);
        }

        emit ActionResolved(heroId, success, xpGain, lootId);
    }

    function _getLootId(uint8 difficulty, uint256 seed) internal pure returns (uint256) {
        // difficulty param reserved for drop tables
        if (difficulty == 0) return ID_POTION_HEAL; // Prevent unused variable warning usage

        uint256 roll = seed % 100;
        if (roll < 50) return ID_POTION_HEAL; 
        if (roll < 85) return ID_SWORD_BASIC;
        return ID_ARMOR_LEATHER;
    }

    // --- Admin ---

    function adminMintItems(address to, uint256 itemId, uint256 amount) external onlyOwner {
        itemsContract.mint(to, itemId, amount, "");
    }
}

